/**
 * Show the error of a route. A NotPermittedError shows the "not permitted"
 * page. A problem details response gives the title and the detail.
 */
export function RouteError({ error }: ErrorComponentProps): ReactNode {
  if (error instanceof NotPermittedError) {
    return <NotPermittedPage />;
  }
  if (error instanceof LoginStartedError) {
    return (
      <p role="status" className="text-muted-foreground">
        Wait for the login page.
      </p>
    );
  }
  let title = "The page cannot open.";
  let detail: string | undefined;
  if (error instanceof ApiError) {
    title = error.title;
    detail = error.detail;
  } else if (error instanceof Error) {
    title = error.message;
  }
  return (
    <Alert variant="destructive">
      <AlertTitle>{title}</AlertTitle>
      {detail === undefined ? null : (
        <AlertDescription>{detail}</AlertDescription>
      )}
    </Alert>
  );
}
